package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art.Art
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait RequestArbiter_governorProcess_requestArbiter_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter)
  }

  /** helper function to set the values of all input ports.
   * @param pilotRequest payload for data port pilotRequest
   * @param chargerState payload for data port chargerState
   * @param recoveryProposal payload for data port recoveryProposal
   */
  def put_concrete_inputs(pilotRequest : Drone_Lifecycle_Governor.LifecycleRequest.Type,
                          chargerState : Drone_Lifecycle_Governor.ChargerState.Type,
                          recoveryProposal : Drone_Lifecycle_Governor.RecoveryProposal.Type): Unit = {
    put_pilotRequest(pilotRequest)
    put_chargerState(chargerState)
    put_recoveryProposal(recoveryProposal)
  }


  /** helper function to check RequestArbiter_governorProcess_requestArbiter's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param arbitratedIntent method that will be called with the value of the outgoing data
   *        port 'arbitratedIntent'.
   */
  def check_concrete_output(arbitratedIntent: Drone_Lifecycle_Governor.ArbitratedIntent => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val arbitratedIntentValue: Drone_Lifecycle_Governor.ArbitratedIntent = get_arbitratedIntent().get
    if(!arbitratedIntent(arbitratedIntentValue)) {
      testFailures = testFailures :+ st"'arbitratedIntent' did not match expected: value of the outgoing data port is ${arbitratedIntentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_pilotRequest(value : Drone_Lifecycle_Governor.LifecycleRequest.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter.operational_api.pilotRequest_Id, Drone_Lifecycle_Governor.LifecycleRequest_Payload(value))
  }

  // setter for in DataPort
  def put_chargerState(value : Drone_Lifecycle_Governor.ChargerState.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter.operational_api.chargerState_Id, Drone_Lifecycle_Governor.ChargerState_Payload(value))
  }

  // setter for in DataPort
  def put_recoveryProposal(value : Drone_Lifecycle_Governor.RecoveryProposal.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter.operational_api.recoveryProposal_Id, Drone_Lifecycle_Governor.RecoveryProposal_Payload(value))
  }

  // getter for out DataPort
  def get_arbitratedIntent(): Option[Drone_Lifecycle_Governor.ArbitratedIntent] = {
    val value: Option[Drone_Lifecycle_Governor.ArbitratedIntent] = get_arbitratedIntent_payload() match {
      case Some(Drone_Lifecycle_Governor.ArbitratedIntent_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port arbitratedIntent.  Expecting 'Drone_Lifecycle_Governor.ArbitratedIntent_Payload' but received ${v}")
      case _ => None[Drone_Lifecycle_Governor.ArbitratedIntent]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_arbitratedIntent_payload(): Option[Drone_Lifecycle_Governor.ArbitratedIntent_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DroneLifecycleGovernorSystem_Instance_governorProcess_requestArbiter.initialization_api.arbitratedIntent_Id).asInstanceOf[Option[Drone_Lifecycle_Governor.ArbitratedIntent_Payload]]
  }

}
